style.css:
/* Midnight Ritual — YouTube */

:root {
  /* swap these colors if you want */
  --my-bg: #0b090c;
  --my-panel: #151116;
  --my-accent: #702d43;
  --my-text: #e8dfe4;
  --my-muted: #94858e;
}

/* dark background */
html,
body {
  background: var(--my-bg) !important;
  color: var(--my-text) !important;
}

/* typography */
body {
  font-family: "Arial", sans-serif !important;
}

/* links */
a {
  color: var(--my-text) !important;
}

/* images and thumbnails */
ytd-thumbnail,
yt-image,
ytd-rich-item-renderer img {
  border-radius: 12px !important;
  overflow: hidden !important;
}

/* panels */
ytd-rich-item-renderer,
ytd-compact-video-renderer {
  background: var(--my-panel) !important;
  border-radius: 14px !important;
}

/* buttons */
yt-button-shape button,
ytd-button-renderer button {
  border-radius: 20px !important;
}

/* scrollbar */
::-webkit-scrollbar {
  width: 8px !important;
}

::-webkit-scrollbar-thumb {
  background: var(--my-accent) !important;
  border-radius: 10px !important;
}
